UPDATE post
SET view_count = view_count + 1
WHERE id = #{postId}
    AND board_id = #{boardId}
    AND deleted_at IS NULL

UPDATE post
SET deleted_at = CURRENT_TIMESTAMP(6),
    version = version + 1
WHERE id = #{postId}
    AND board_id = #{boardId}
    AND version = #{version}
    AND deleted_at IS NULL
